(function(root){'use strict';
const MARKERS=/【(?:KẾT QUẢ CHẤM WRITING|HẾT KẾT QUẢ CHẤM)】/g,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tone=text=>/KHÔNG ĐƯỢC CHẤM|CHƯA ĐẠT/iu.test(text)?'danger':/Cần sửa|nộp lại/iu.test(text)?'warning':/Đã trả/iu.test(text)?'info':/Chưa nộp/iu.test(text)?'neutral':'success';
const status=text=>/^(?:(?:Đề\s+\d+\s*:\s*)?(?:Đạt yêu cầu(?: bài tập)?|Cần sửa và nộp lại)|(?:VỞ )?(?:ĐÃ )?ĐẠT YÊU CẦU|VỞ CHƯA ĐẠT YÊU CẦU|KHÔNG ĐƯỢC CHẤM BÀI(?: VIẾT)?|Đã trả\s+\d+\s*\/\s*\d+\s+bài chữa(?: trên dashboard)?)[.!]?$/iu.test(text.trim());
function badge(text){return '<span class="ielts48-review-badge '+tone(text)+'">'+esc(text)+'</span>';}
function writing(text,base){const lines=String(text||'').replace(MARKERS,'').split(/\n+/).map(t=>t.trim()).filter(Boolean);return '<div class="ielts48-writing-feedback">'+lines.map(line=>status(line)?badge(line):base(line)).join('')+'</div>';}
function tidy(host){const walk=document.createTreeWalker(host,NodeFilter.SHOW_TEXT),nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);for(const node of nodes){const parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,.ielts48-review-badge'))continue;const clean=node.nodeValue.replace(MARKERS,'');if(node.nodeValue!==clean)node.nodeValue=clean;const text=clean.trim();if(!text)continue;if(status(text)){if(parent.childNodes.length===1&&!parent.matches('a,button,summary'))parent.classList.add('ielts48-review-badge',tone(text));else{const span=document.createElement('span');span.className='ielts48-review-badge '+tone(text);span.textContent=text;node.replaceWith(span);}}else{const match=/Đã trả\s+\d+\s*\/\s*\d+\s+bài chữa/iu.exec(clean);if(match){const fragment=document.createDocumentFragment();fragment.append(document.createTextNode(clean.slice(0,match.index)));const span=document.createElement('span');span.className='ielts48-review-badge info';span.textContent=match[0];fragment.append(span,document.createTextNode(clean.slice(match.index+match[0].length)));node.replaceWith(fragment);}}}}
const normalized=text=>String(text||'').toLocaleLowerCase('vi').replace(/\s+/g,' ').replace(/[.!]$/,'').trim();
function deduplicate(host){const rich=host.querySelector('.wr-assignment:not([aria-busy="true"])');if(!rich)return;const rendered=normalized(rich.textContent);for(const legacy of host.querySelectorAll('.ielts48-writing-feedback')){for(const child of [...legacy.children]){const text=normalized(child.textContent).replace(/\s+trên dashboard$/,'').replace(/^đề\s+\d+\s*:\s*/,'').replace(/^vở chưa đạt\s*:\s*/,'');if(text&&rendered.includes(text))child.remove();}if(!legacy.textContent.trim())legacy.remove();}}
function html(source){const template=document.createElement('template');template.innerHTML=source;tidy(template.content);deduplicate(template.content);return template.innerHTML;}
function observe(host){tidy(host);deduplicate(host);const observer=new MutationObserver(()=>{tidy(host);deduplicate(host);});observer.observe(host,{childList:true,characterData:true,subtree:true});return()=>observer.disconnect();}
root.Ielts48ReviewFormat={writing,html,tidy,observe,badge,tone,hasMarkers:text=>/【(?:KẾT QUẢ CHẤM WRITING|HẾT KẾT QUẢ CHẤM)】/.test(String(text||''))};
})(globalThis);
